G=load(); print({k:(len(v),len(v[0])) for k,v in G.items()})
def shapes(grid):
    # connected components (4-neighborhood) of nonzero cells, in reading order
    import sys; sys.setrecursionlimit(10000)
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and (i,j) not in seen:
                stack=[(i,j)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx] and (ny,nx) not in seen: stack.append((ny,nx))
                out.append(comp)
    return out
def bbox(g,comp):
    ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
    return [[g[i][j] if g[i][j] else 0 for j in range(min(xs),max(xs)+1)] for i in range(min(ys),max(ys)+1)]
def transform(grid):
    comps=sorted(shapes(grid), key=lambda c: (min(p[0] for p in c), min(p[1] for p in c)))
    bbs=[bbox(grid,c) for c in comps]
    h=max(len(b) for b in bbs)
    rows=[[] for _ in range(h)]
    for b in bbs:
        for i in range(h):
            rows[i]+= b[i] if i<len(b) else [0]*len(b[0])
    return rows
